function currentUrl(actions) {
  let stack = [];
  for (let i = 0; i < actions.length; i++) {
    let [action, value] = actions[i];
    if (action === "go") {
      stack.push(value);
    } else {
      while (stack.length > 1 && value > 0) {
        stack.pop();
        value -= 1;
      }
    }
  }
  return stack[stack.length - 1];
}

