class CurrentUrl {
  public String solve(String[][] actions) {
    Stack<String> stack = new Stack<>();
    for (String[] action : actions) {
      if (action[0].equals("go")) {
        stack.push(action[1]);
      } else {
        int backSteps = Integer.parseInt(action[1]);
        while (stack.size() > 1 && backSteps > 0) {
          stack.pop();
          backSteps--;
        }
      }
    }
    return stack.peek();
  }
}

